def countdown_sum(n):
    total = 0
    while n > 0:
        total += n
        n -= 1
    return total

def sum_evens(limit):
    total = 0
    for i in range(2, limit + 1, 2):
        total += i
    return total

def get_positives(numbers):
    pos = []
    for x in numbers:
        if x > 0:
            pos.append(x)
    return pos

def compute(a):
